export class CheckoutService {
  constructor(private cart: CartRepo, private pricing: Pricing, private payments: PaymentGateway, private mailer: Mailer) {}
  async checkout(userId: string, coupon?: string) {
    const cart = await this.cart.load(userId);
    const total = this.pricing.total(cart.items, coupon);
    const receipt = await this.payments.charge(userId, total);
    await this.cart.clear(userId);
    await this.mailer.sendReceipt(userId, receipt);
    return receipt;
  }
}
```
We use Vitest and Playwright. Pricing is pure.
